function ScreenHead({ title, help }) {
  return (
    <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between",
      gap: 12, marginBottom: 12 }}>
      <h1 style={{ margin: 0, fontSize: 20, fontWeight: 700, color: baseTokens.ink }}>{title}</h1>
      {help && <HowThisWorks id={help} />}
    </div>
  );
}


function Collapsible({ title, badge, defaultOpen, children }) {
  const [open, setOpen] = useState(!!defaultOpen);
  return (
    <Card style={{ padding: 0, overflow: "hidden" }}>
      <div onClick={() => setOpen(o => !o)} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "11px 13px", cursor: "pointer" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ fontSize: 12.5, fontWeight: 700, color: baseTokens.ink }}>{title}</span>
          {badge != null && <Pill tone="gray">{badge}</Pill>}
        </div>
        <ChevronDown size={15} color={baseTokens.textM} style={{ transform: open ? "rotate(180deg)" : "none", transition: "transform .15s" }} />
      </div>
      {open && <div style={{ padding: "0 13px 13px" }}>{children}</div>}
    </Card>
  );
}

