function TrendSpark({ series, cls, note }) {
  const w = 168, h = 38, min = Math.min(...series), max = Math.max(...series), span = max - min || 1;
  const pts = series.map((v, i) => `${(i / (series.length - 1)) * (w - 6) + 3},${h - 4 - ((v - min) / span) * (h - 10)}`).join(" ");
  const broke = cls.indexOf("break") >= 0;
  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
        <svg width={w} height={h} style={{ background: "#f8fafc", border: `1px solid ${baseTokens.border}`, borderRadius: 6 }}>
          <polyline points={pts} fill="none" stroke={broke ? "#b45309" : "#0e7490"} strokeWidth="1.8" />
          {series.map((v, i) => <circle key={i} cx={(i / (series.length - 1)) * (w - 6) + 3} cy={h - 4 - ((v - min) / span) * (h - 10)} r={i === series.length - 1 ? 3 : 1.8} fill={broke ? "#b45309" : "#0e7490"} />)}
        </svg>
        <Pill tone={broke ? "amber" : "green"}>{cls}</Pill>
      </div>
      <p style={{ margin: 0, fontSize: 11, color: baseTokens.textM }}>{note}</p>
    </div>
  );
}

