function ImpactDAG({ d }) {
  const pos = {}; d.nodes.forEach(n => pos[n.id] = n);
  return (
    <div>
      <svg viewBox="0 0 220 162" style={{ width: "100%", maxWidth: 260, background: "#f8fafc", border: `1px solid ${baseTokens.border}`, borderRadius: 8 }}>
        {d.edges.map(([f, t], i) => <line key={i} x1={pos[f].x} y1={pos[f].y} x2={pos[t].x} y2={pos[t].y} stroke="#cbd5e1" strokeWidth="1.5" />)}
        {d.nodes.map(n => (
          <g key={n.id}>
            <circle cx={n.x} cy={n.y} r={n.conv ? 9 : 7} fill={n.conv ? "#b91c1c" : "#1e293b"} />
            <text x={n.x} y={n.y + 3} textAnchor="middle" fontSize="8" fill="#fff" fontWeight="700">{n.id}</text>
            <text x={n.x + 14} y={n.y + 3} textAnchor="start" fontSize="8.5" fill="#475569">{n.ref}</text>
          </g>
        ))}
      </svg>
      <p style={{ margin: "7px 0 0", fontSize: 11, color: baseTokens.textM }}>{d.note}</p>
    </div>
  );
}

function ImpactRows({ rows }) {
  return (
    <div style={{ border: `1px solid ${baseTokens.border}`, borderRadius: 8, overflow: "hidden" }}>
      <div style={{ display: "grid", gridTemplateColumns: "1.35fr 44px 92px 118px", background: "#f8fafc", fontSize: 10, fontWeight: 700, color: baseTokens.textM, padding: "6px 10px" }}>
        <span>NODE</span><span>DIST</span><span>Δ (verbatim)</span><span>MATERIALITY</span></div>
      {rows.map((r, i) => {
        const m = MAT_META[r[4]];
        return (
          <div key={i} title={r[5] || undefined} style={{ display: "grid", gridTemplateColumns: "1.35fr 44px 92px 118px", fontSize: 11.5, padding: "6px 10px", borderTop: `1px solid ${baseTokens.border}`, alignItems: "center", background: r[1] === "subject" ? "#f8fafc" : "#fff" }}>
            <span style={{ display: "flex", gap: 5, alignItems: "center", minWidth: 0 }}>
              <span style={{ fontFamily: baseTokens.mono, fontWeight: r[1] === "subject" ? 700 : 500, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r[0]}</span>
              {r[1] && <Pill tone={r[1] === "subject" ? "blue" : "purple"}>{r[1]}</Pill>}
            </span>
            <span style={{ color: baseTokens.textM }}>{r[2]}</span>
            <span style={{ fontWeight: 600, color: r[4] === "direction_only" ? "#b45309" : baseTokens.ink }}>{r[3]}</span>
            <span><Pill tone={m.tone}>{m.label}</Pill></span>
          </div>
        );
      })}
      <div style={{ padding: "6px 10px", borderTop: `1px solid ${baseTokens.border}`, fontSize: 10, color: baseTokens.textL }}>Hover a degraded row for its reason — the ladder is visible, never silent. Δ display strings are host-resolved and rendered VERBATIM; direction-only rows never show a magnitude.</div>
    </div>
  );
}

function ImpactChecks({ checks }) {
  return (
    <div style={{ display: "grid", gap: 5 }}>
      {checks.map((c, i) => (
        <div key={i} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, border: `1px solid ${baseTokens.border}`, borderRadius: 7, padding: "6px 10px" }}>
          <span style={{ fontSize: 12, fontFamily: baseTokens.mono, fontWeight: 600, color: baseTokens.ink }}>{c[0]}</span>
          <span style={{ fontSize: 11, color: baseTokens.textM, flex: 1, textAlign: "center" }}>{c[1]}</span>
          <Pill tone={CHECK_TONE[c[2]]}>{c[2]}</Pill>
          <span style={{ fontSize: 10, color: baseTokens.textL, minWidth: 120, textAlign: "right" }}>{c[3]}</span>
        </div>
      ))}
    </div>
  );
}

function ImpactDrawer({ scenario, onClose, openEvidence }) {
  const sc = scenario;
  const [hostEval, setHostEval] = useState(false);
  const checks = sc.evalSwitch ? (hostEval ? sc.checksHost : sc.checksLocal) : sc.checks;
  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(15,23,42,.35)", zIndex: 50, display: "flex", justifyContent: "flex-end" }}>
      <div onClick={e => e.stopPropagation()} style={{ width: 490, maxWidth: "94vw", background: "#fff", height: "100vh", maxHeight: "100vh", display: "flex", flexDirection: "column" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "13px 16px", background: "linear-gradient(90deg,#0f172a,#1e293b)" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 9 }}>
            <GitBranch size={16} color="#fff" />
            <div>
              <div style={{ fontSize: 13.5, fontWeight: 700, color: "#fff" }}>Lextr Intelligence · Impact analysis</div>
              <div style={{ fontSize: 10.5, color: "#94a3b8" }}>{sc.tag} · slide-over served into Core · UC2</div>
            </div>
          </div>
          <X size={18} color="#94a3b8" style={{ cursor: "pointer" }} onClick={onClose} />
        </div>
        <div style={{ overflowY: "auto", flex: 1, minHeight: 0, padding: 14, display: "grid", gap: 12 }}>
          {/* subject + change */}
          <Card style={{ padding: 13 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
              <div style={{ minWidth: 0 }}>
                <Eyebrow>Assessing</Eyebrow>
                <div style={{ fontSize: 13.5, fontWeight: 700, color: baseTokens.ink }}>{sc.subject}</div>
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 7 }}>
                  <Pill tone="purple">{sc.kindLabel}</Pill>
                  <Pill tone="blue">{sc.change}</Pill>
                  <Pill tone={sc.scope === "cross_report" ? "amber" : "teal"}>{sc.scope}</Pill>
                </div>
              </div>
              <div style={{ textAlign: "right" }}>
                <Eyebrow>Coverage (signal)</Eyebrow>
                <Pill tone="green">{sc.coverage}</Pill>
              </div>
            </div>
          </Card>

          {/* the no-SLM guardrail — always visible */}
          <div style={{ display: "flex", gap: 8, alignItems: "flex-start", background: "#f0fdf4", border: "1px solid #bbf7d0", borderRadius: 8, padding: "9px 11px" }}>
            <Shield size={13} color="#15803d" style={{ marginTop: 1 }} />
            <span style={{ fontSize: 11.5, color: "#166534" }}><b>Deterministic — no model call.</b> Both passes are arithmetic + rule evaluation; the summary is a fixed template. Three-layer guardrail: no model port on the skill · model-bound presets rejected · no model op on the OPA allow-list.</span>
          </div>

          {sc.empty ? (
            /* honest empty — the reason IS the answer */
            <Card style={{ padding: 13, border: "1px solid #fde68a", background: "#fffbeb" }}>
              <Eyebrow>No reachable impact — and exactly why</Eyebrow>
              <div style={{ fontSize: 12, fontFamily: baseTokens.mono, color: "#92400e", lineHeight: 1.5 }}>{sc.reason}</div>
              <p style={{ margin: "8px 0 0", fontSize: 11.5, color: baseTokens.textM }}>{sc.note}</p>
              <p style={{ margin: "8px 0 0", fontSize: 11, color: baseTokens.textL }}>Fail-closed, never silent — this empty is an ANSWER: persisted as one agent_run and queued for lightweight review like any other.</p>
            </Card>
          ) : (
            <>
              {/* fixed template summary */}
              <Card style={{ padding: 13 }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 6 }}>
                  <Eyebrow>Summary — fixed template, never generative</Eyebrow>
                  <Pill tone="gray">impact_list</Pill>
                </div>
                <p style={{ margin: 0, fontSize: 12.5, lineHeight: 1.55, color: baseTokens.text }}>{sc.narrative}</p>
              </Card>

              {sc.nonValue && (
                <div style={{ display: "flex", gap: 8, alignItems: "flex-start", background: "#eff6ff", border: "1px solid #bfdbfe", borderRadius: 8, padding: "9px 11px" }}>
                  <Info size={13} color="#1d4ed8" style={{ marginTop: 1 }} />
                  <span style={{ fontSize: 11.5, color: "#1e3a8a" }}><b>Non-value change:</b> no per-line Δ is derivable at change time — the reach below is structural BY CONSTRUCTION and the affected checks are IDENTIFIED (evaluation deferred to Core re-derivation). Nothing is fabricated.</span>
                </div>
              )}

              {/* affected rows */}
              {sc.rows && (
                <Card style={{ padding: 13 }}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
                    <Eyebrow>Affected rows (Pass 1 reach · Pass 2 Δ)</Eyebrow>
                    <Pill tone="gray">{sc.rows.length}</Pill>
                  </div>
                  <ImpactRows rows={sc.rows} />
                </Card>
              )}

              {/* checks */}
              {checks && (
                <Card style={{ padding: 13 }}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
                    <Eyebrow>Affected edit-checks — only the checks this Δ touches (never UC7's full suite)</Eyebrow>
                    <Pill tone="gray">{checks.length}</Pill>
                  </div>
                  {sc.evalSwitch && (
                    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 9, border: `1px dashed ${baseTokens.borderL}`, borderRadius: 8, padding: "7px 10px" }}>
                      <span style={{ fontSize: 11.5, color: baseTokens.textM }}>OPA datum <span style={{ fontFamily: baseTokens.mono }}>evaluate_ready</span>:</span>
                      <span onClick={() => setHostEval(v => !v)} style={{ cursor: "pointer", padding: "3px 10px", borderRadius: 999, fontSize: 11, fontWeight: 700, background: hostEval ? "#16a34a" : "#f1f5f9", color: hostEval ? "#fff" : baseTokens.textM }}>{hostEval ? "true — Core DAG engine AUTHORITATIVE" : "false — local closed-subset evaluator"}</span>
                      <span style={{ fontSize: 10.5, color: baseTokens.textL }}>a datum flip — zero code change</span>
                    </div>
                  )}
                  <ImpactChecks checks={checks} />
                </Card>
              )}

              {/* lineage */}
              {sc.dag && (
                <Card style={{ padding: 13 }}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
                    <Eyebrow>Lineage (forward walk)</Eyebrow>
                    <Pill tone="gray"><GitBranch size={11} />convergence-once</Pill>
                  </div>
                  <ImpactDAG d={sc.dag} />
                </Card>
              )}

              {/* ladder + bounds */}
              <Card style={{ padding: 13 }}>
                <Eyebrow>The degradation ladder — honest by construction</Eyebrow>
                <div style={{ display: "grid", gap: 5 }}>
                  {IMPACT_LADDER.map((l, i) => (
                    <div key={i} style={{ display: "flex", gap: 8, alignItems: "center" }}>
                      <span style={{ minWidth: 110 }}><Pill tone={l[1]}>{l[0]}</Pill></span>
                      <span style={{ fontSize: 11.5, color: baseTokens.textM }}>{l[2]}</span>
                    </div>
                  ))}
                </div>
                <div style={{ fontSize: 10.5, color: baseTokens.textL, marginTop: 9 }}>Bounds recorded: {sc.boundsNote}. EXCLUDED/MNPI never returned; masked operands never unmasked; nothing fabricated.</div>
              </Card>

              {sc.note && <div style={{ fontSize: 11.5, color: baseTokens.textM, background: "#f8fafc", border: `1px solid ${baseTokens.border}`, borderRadius: 8, padding: "9px 11px" }}>{sc.note}</div>}

              {sc.scope !== "cross_report" && (
                <div style={{ fontSize: 11, color: baseTokens.textL }}>Cross-report impact unavailable — cross-report edges not built (cross_report_ready=false). Within-report reach shown above.</div>
              )}
            </>
          )}

          <ReviewBanner />
          <div style={{ display: "flex", gap: 8 }}>
            <Btn kind="sec" onClick={openEvidence}><Eye size={13} /> Open evidence ledger</Btn>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   UC11 — COA Rules & Logic Assist. The EMBEDDED copilot (DD-36).

   This deliberately does NOT follow the variance drawer pattern. Variance is a
   DRAWER: Core owns a grid, the analyst asks "explain", and Intelligence slides
   an explanation over the top. UC11 is EMBEDDED: Core owns a rule-authoring
   screen and MOUNTS the copilot beside its own form. There is no route, no
   slide-over and nothing to navigate to.

   The load-bearing behaviour to look for:
     * accepting a finding APPLIES A PATCH to the draft in Core's editor — the
       author never retypes and never copies (DD-37);
     * the SAME patch projects into either surface — an inline decoration in the
       DSL text, a node highlight or ghost node in the drag-drop builder;
     * editing the draft makes existing findings STALE rather than hiding them;
     * REVIEW cannot generate, and says so;
     * Core's own Save / Submit controls stay live throughout — nothing here
       blocks the conventional path.
   ═══════════════════════════════════════════════════════════════════════════ */

/* ═══════════════════════════════════════════════════════════════════════════
   UC11 — COA Rules & Logic Assist. The EMBEDDED copilot (DD-36), redesigned.

   Architecture unchanged: embedded beside Core's form, structural node-anchored
   patches (DD-37), no data-value op, Core owns the DSL, grammar, versioning and
   the maker-checker workflow.

   What changed is WHAT THE PANEL SHOWS. The first build rendered only verdicts —
   every DTO was a judgement — while the six sources the skill fetches on every
   run were read, used, and discarded. The author never saw what we read, only our
   opinions about it. Now the content leads and the findings are layered onto it.

   FOUR TABS, one per question an author actually asks:
     Understand — what is this line asking for?   (instruction + composed definition)
     Build      — what can I use?                 (semantic catalog + governed values)
     Check      — is what I wrote right?          (the findings; formerly the whole UI)
     Compare    — has someone solved this already? (sibling rules + analogy)

   EVERYTHING HERE COMES THROUGH THE SEMANTIC LAYER, which exposes LOGICAL names
   only. No physical table or column is reachable from this surface, because the
   surface has no access to one.
   ═══════════════════════════════════════════════════════════════════════════ */

