const TDM_DS_STEPS = ["Identity & Tenant", "Axes & Purpose", "Loading & Inbox", "Ring-fence (OPA)", "Review & Create"];
function DatasetWizardDraft({ refId, onDiscard, onCommit }) {
  const [step, _setStep] = useState(1);
  /* D13a · how far you GOT, kept apart from where you ARE, so stepping back does not un-tick
     work already done. Both wizards behave the same way because both use one component. */
  const [reached, setReached] = useState(1);
  /* Accepts a NUMBER or an updater, because Back passes `x => x - 1` and Math.max(r, fn) is NaN
     — which silently destroyed `reached` and un-ticked every completed step. */
  const setStep = (n) => _setStep(prev => {
    const v = typeof n === "function" ? n(prev) : n;
    if (v > reached) setReached(v);
    return v;
  });
  const [purpose, setPurpose] = useState("training");
  const next = () => { setStep(x => Math.min(TDM_DS_STEPS.length, x + 1)); };
  return (
    <DraftShell refId={refId} title="Create dataset" onDiscard={onDiscard}>
      <WizardSteps steps={TDM_DS_STEPS} step={step} reached={reached} onStep={setStep} />
      <div style={{ minHeight: 150 }}>
        <div style={{ fontSize: 12.5, fontWeight: 700, color: baseTokens.ink, marginBottom: 10 }}>{TDM_DS_STEPS[step - 1]}</div>
        {step === 1 && (<div style={{ display: "grid", gap: 8, maxWidth: 520 }}>
          <Field label="Dataset name"><MiniInput value="variance_client_002" /></Field>
          <Field label="Tenant (ring-fence — a dataset belongs to ONE tenant)" hint="Cross-tenant contribution is structurally impossible: every load targets one dataset."><MiniInput value="client_002" /></Field>
        </div>)}
        {step === 2 && (<div style={{ display: "grid", gap: 8, maxWidth: 560 }}>
          <div style={{ fontSize: 11.5, color: baseTokens.textM }}>Purpose — same lifecycle and governance either way; evaluation datasets feed the harness and are NEVER trained on:</div>
          <div style={{ display: "flex", gap: 6 }}>
            <Btn kind={purpose === "training" ? "primary" : "sec"} onClick={() => setPurpose("training")}>training</Btn>
            <Btn kind={purpose === "evaluation" ? "primary" : "sec"} onClick={() => setPurpose("evaluation")}>evaluation (held-out suite)</Btn>
          </div>
          <Field label="Task"><MiniInput value="variance_explanation" /></Field>
          <Field label="Report family"><MiniInput value="FR Y-9C" /></Field>
          <Field label="Purpose note"><MiniInput value="Tenant-local phrasing + methodology exemplars" /></Field>
          {purpose === "evaluation" && <div style={{ fontSize: 10.5, color: baseTokens.amber }}>Contamination gate applies at every freeze: no sample may belong to both this suite and any training dataset whose models it scores.</div>}
        </div>)}
        {step === 3 && (<div style={{ display: "grid", gap: 8 }}>
          <div style={{ fontSize: 11.5, color: baseTokens.textM, lineHeight: 1.8 }}>Creating a dataset = naming its FIRST OPEN DRAFT (v1 draft opens empty). Loading paths into the draft:<br />· Path A — designate as the tenant's AUTO-ROUTED inbox for this task × report (review-correction capture; opt-in per run)<br />· Path B — SME authoring (+ Add Sample wizard)<br />· Path C — Data Steward bulk import</div>
          <label style={{ display: "flex", gap: 8, alignItems: "center", fontSize: 12, color: baseTokens.text }}><input type="checkbox" defaultChecked /> Designate as the path-A inbox for variance × Y-9C (client_002)</label>
        </div>)}
        {step === 4 && (<div style={{ display: "grid", gap: 6 }}>
          <div style={{ fontSize: 11.5, color: baseTokens.textM }}>Bound at creation — REFERENCES to OPA, never inlined:</div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>{["OPA-TDM-001 AI_PROHIBITED never", "OPA-TDM-002 RESTRICTED masked-only", "OPA-TDM-003 tenant ring-fence", "OPA-TDM-004 on-prem never leaves", "OPA-TDM-005 SoD curator ≠ approver"].map(x => <Pill key={x} tone="purple"><Shield size={10} />{x}</Pill>)}</div>
        </div>)}
        {step === 5 && (<div style={{ fontSize: 11.5, color: baseTokens.textM, lineHeight: 1.9 }}>Creates <b style={{ color: baseTokens.text }}>variance_client_002</b> (purpose <b style={{ color: baseTokens.text }}>{purpose}</b> · tenant client_002 · variance × Y-9C) with its v1 OPEN DRAFT — status draft. The dataset ID (TD-…) is assigned SERVER-SIDE on create; the draft ref above is client-side only. First freeze will require: hash → masking attestation (Data Steward) → MRM approval (SoD). Evidenced on create.</div>)}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", marginTop: 14 }}>
        <Btn kind="sec" disabled={step === 1} onClick={() => setStep(x => Math.max(1, x - 1))}>Back</Btn>
        {step < TDM_DS_STEPS.length ? <Btn kind="primary" onClick={next}>Next</Btn> : <Btn kind="primary" onClick={onCommit}>Create dataset (opens v1 draft)</Btn>}
      </div>
    </DraftShell>
  );
}
