function skillEnabled(s) {
  return s.lifecycle === "operational" && s.requiredCapabilities.every(c => HOST_CAPS[c]);
}
function skillOpCount(s) {
  return s.toolScopeOps.filter(o => !o.trim().startsWith("—")).length;
}

function LifecycleTrack({ current }) {
  const stages = ["draft", "observed", "operational"];
  const idx = stages.indexOf(current);
  const fill = { draft: baseTokens.amber, observed: baseTokens.blue, operational: baseTokens.green };
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
      {stages.map((st, i) => (
        <React.Fragment key={st}>
          <span style={{ fontSize: 10.5, fontWeight: 700, textTransform: "capitalize", padding: "3px 10px", borderRadius: 6,
            color: i === idx ? "#fff" : baseTokens.textM, background: i === idx ? fill[st] : "#f1f5f9",
            border: `1px solid ${i === idx ? "transparent" : baseTokens.border}`, opacity: i <= idx ? 1 : 0.5 }}>{st}</span>
          {i < stages.length - 1 && (
            <span style={{ display: "inline-flex", alignItems: "center", gap: 1, color: baseTokens.textL }} title={i === 1 ? "MRM-gated transition" : undefined}>
              <ArrowRight size={13} />{i === 1 && <Lock size={10} />}
            </span>
          )}
        </React.Fragment>
      ))}
    </div>
  );
}

